-- 0076 — POSTCHECK. READ ONLY: one SELECT, changes nothing. Generated by supabase/live/make_blocks_pack.sh — do not edit by hand.
-- Run right after 0076. Every row must be ok = true.
with checks(item, ok, detail) as (
  select 'blocks policies unchanged (the current website still inserts directly)', (select coalesce(string_agg(policyname || ' (' || cmd || ')', ', ' order by policyname), 'none') from pg_policies where schemaname = 'public' and tablename = 'blocks') = 'blocks: staff read (SELECT), blocks: staff write (ALL)', (select coalesce(string_agg(policyname || ' (' || cmd || ')', ', ' order by policyname), 'none') from pg_policies where schemaname = 'public' and tablename = 'blocks')
  union all select 'staff_block: new in 0076', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '1e8dc62bedc9d9bbadcfd68cd906b71d' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'staff_block'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'staff_block'), 'missing')
  union all select 'assert_valid_block: new in 0076', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '443366cc1f3829e0bc3991c238b5c90c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_block'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_block'), 'missing')
  union all select 'blocks_direct_write_rules: new in 0076', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '58ae4fef2de6a7daaca5d9a48b639525' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'blocks_direct_write_rules'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'blocks_direct_write_rules'), 'missing')
  union all select 'reject_block_over_booking: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '18c335039c80db474319e30ddbde01ec' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_block_over_booking'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_block_over_booking'), 'missing')
  union all select 'reject_booking_over_block: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '1c955f6aaf4eed5d27a8be8032ca149f' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_booking_over_block'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_booking_over_block'), 'missing')
  union all select 'expire_stale_holds: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'bd5333a933065bffc0599dcee74b389d' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'expire_stale_holds'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'expire_stale_holds'), 'missing')
  union all select 'assert_valid_court_slot: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '842d14da33899a48cb53eb356bdf671c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_court_slot'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_court_slot'), 'missing')
  union all select 'close_club: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '5374dc2a493362cdc644fb0c65256f42' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'close_club'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'close_club'), 'missing')
  union all select 'is_staff_of: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '2fd33ea362331532c1508cdb70777296' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'is_staff_of'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'is_staff_of'), 'missing')
  union all select 'staff_block: owner rights, fixed search path, signed-in users only', coalesce(has_function_privilege('authenticated', to_regprocedure('public.staff_block(uuid,uuid,timestamptz,timestamptz,text)'), 'execute') and not has_function_privilege('anon', to_regprocedure('public.staff_block(uuid,uuid,timestamptz,timestamptz,text)'), 'execute') and (select prosecdef and proconfig = '{search_path=public}' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'staff_block') and not has_function_privilege('anon', to_regprocedure('public.assert_valid_block(uuid,uuid,timestamptz,timestamptz)'), 'execute'), false), ''
  union all select 'direct-write rule: trigger blocks_direct_write_rules enabled', exists (select 1 from pg_trigger where tgrelid = 'public.blocks'::regclass and tgname = 'blocks_direct_write_rules' and tgenabled = 'O'), (select coalesce(string_agg(tgname, ', ' order by tgname), 'none') from pg_trigger where tgrelid = 'public.blocks'::regclass and not tgisinternal)
  union all select 'overlap protection in place', exists (select 1 from pg_trigger where tgrelid = 'public.blocks'::regclass and tgname = 'blocks_booking_check' and tgenabled = 'O') and exists (select 1 from pg_trigger t join pg_proc p on p.oid = t.tgfoid where t.tgrelid = 'public.bookings'::regclass and p.proname = 'reject_booking_over_block' and t.tgenabled = 'O') and exists (select 1 from pg_constraint where conrelid = 'public.blocks'::regclass and conname = 'no_overlapping_blocks' and contype = 'x'), ''
  union all select 'saved blocks: same as in the preflight (information)', true, (select count(*) || ' blocks, ' || coalesce(md5(string_agg(id::text || '|' || club_id || '|' || court_id || '|' || start_at || '|' || end_at || '|' || coalesce(reason, '') || '|' || created_by || '|' || created_at, ',' order by id)), '-') from public.blocks)
)
select item, ok, detail from checks order by item;
